"""Evaluation helpers.

Every function takes the anomaly scores first and the labels second, so labels
are only ever consumed *after* the model has produced its predictions
(requirements R9 and R10).
"""

from __future__ import annotations

import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score

__all__ = ["roc_auc", "auc_pr", "auc_pr_trapz", "summarize"]


def roc_auc(scores, y):
    """AUC-ROC (requirement R9)."""
    return float(roc_auc_score(np.asarray(y).ravel(), np.asarray(scores).ravel()))


def auc_pr(scores, y):
    """AUC-PR via ``sklearn.metrics.average_precision_score`` (ADBench convention)."""
    return float(average_precision_score(np.asarray(y).ravel(), np.asarray(scores).ravel()))


def auc_pr_trapz(scores, y):
    """AUC-PR as the trapezoidal area under the precision-recall curve."""
    y = np.asarray(y).ravel()
    s = np.asarray(scores).ravel()
    precision, recall, _ = precision_recall_curve(y, s)
    return float(np.trapezoid(precision, recall))


def summarize(values):
    """mean / std / min / max over the repeated runs (requirement R8)."""
    v = np.asarray(list(values), dtype=np.float64)
    if v.size == 0:
        return {"n": 0, "mean": None, "std": None, "min": None, "max": None}
    return {
        "n": int(v.size),
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "values": [float(x) for x in v],
    }

